def algorithm(func, dim, lb, ub, budget, rng):
    x_best = -np.inf
    x = np.random.uniform(lb, ub, (1, dim))
    s = 5.0
    for _ in range(budget):
        if func(x).flatten()[0] > x_best:
            x_best = func(x).flatten()[0]
        x = np.clip(np.random.uniform(-s, s, (1, dim)) + x, lb, ub)
        s *= 0.9
    return x[0]
